Definition OBINIT_STACK : Z := 32 + AINTRIN_STACK.

Section HCW.
  Context {HCEIL : HeapCeil}.

Definition obinit_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P E lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (E, E + 24); (P + 240, P + 241)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' E (ErrCodeCells EC_clear)
    /\ rw_cells asegs m' (P + 240) [C1 (b8 1)]
    /\ ACONST m'.

(* [comment removed for export] *)
Definition obinit_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P E lo : Z) (rdi : byte) (ej : list byte),
  rw_cells asegs m (P + 240) [C1 rdi] ->
  rw_cells asegs m E [CB 24 ej] ->
  (P + 241 <= E \/ E + 24 <= P + 240) ->
  stk asegs m lo (bv_unsigned sp) -> lo + OBINIT_STACK <= bv_unsigned sp -> aceil <= lo ->
  aapp E 24 -> aapp (P + 240) 8 -> (P + 240) mod 8 = 0 ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  ACONST m -> accessible m E 24 -> shvis m E (E + 24) -> accessible m (P + 240) 8 ->
  evt asegs (obinit_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P E lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) a1 (wz E) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_ON_BODY_INIT_IMPL) fc None m (seg_rom asegs)).

  Hypothesis MEMSET : asan_memset_stmt.

Lemma zeros24_cells' : forall m E, rw_cells asegs m E [CB 24 (poison_bytes 24 0)] -> rw_cells asegs m E (ErrCodeCells EC_clear).
Proof.
  intros m E V. unfold ErrCodeCells, EC_clear. cbn [ec_val ec_cat ec_flags].
  eapply rw_cells_reshape; [exact V| cbn; repeat split; reflexivity| vm_compute; reflexivity].
Qed.
